{
  "findings": [
    {
      "check_id": "CKV_AWS_66",
      "title": "Ensure that CloudWatch Log Group specifies retention days",
      "resource": "aws_cloudwatch_log_group.CIS_CloudWatch_LogsGroup",
      "severity": "LOW",
      "explanation": "The CloudWatch Log Group referenced in the given Terraform code does not specify retention days, which could lead to indefinite log storage and increased costs."
    },
    {
      "check_id": "CKV_AWS_338",
      "title": "Ensure CloudWatch log groups retains logs for at least 1 year",
      "resource": "aws_cloudwatch_log_group.CIS_CloudWatch_LogsGroup",
      "severity": "MEDIUM",
      "explanation": "The CloudWatch Log Group referenced in the given Terraform code does not ensure log retention for at least 1 year, potentially leading to loss of historical log data."
    },
    {
      "check_id": "CKV_AWS_158",
      "title": "Ensure that CloudWatch Log Group is encrypted by KMS",
      "resource": "aws_cloudwatch_log_group.CIS_CloudWatch_LogsGroup",
      "severity": "MEDIUM",
      "explanation": "The CloudWatch Log Group referenced in the given Terraform code is not explicitly encrypted by KMS, potentially exposing sensitive log data."
    }
  ],
  "patched_code": "resource "aws_cloudwatch_log_group" "CIS_CloudWatch_LogsGroup" {
  name              = "CIS-CloudWatch-LogsGroup"
  retention_in_days = 365
  kms_key_id        = aws_kms_key.cloudwatch_log_group_key.arn
}

resource "aws_kms_key" "cloudwatch_log_group_key" {
  description             = "KMS key for CloudWatch Log Group"
  enable_key_rotation     = true
  deletion_window_in_days = 30
}

resource "aws_cloudwatch_log_metric_filter" "CIS_AWS_Config_Change_Metric_Filter" {
  name           = "CIS-AWSConfigChanges"
  pattern        = "{ ($.eventSource = \"config.amazonaws.com\") && (($.eventName=StopConfigurationRecorder)||($.eventName=DeleteDeliveryChannel)||($.eventName=PutDeliveryChannel)||($.eventName=PutConfigurationRecorder)) }"
  log_group_name = aws_cloudwatch_log_group.CIS_CloudWatch_LogsGroup.name

  metric_transformation {
    name      = "CIS-AWSConfigChanges"
    namespace = "CIS_Metric_Alarm_Namespace"
    value     = "1"
  }
}
resource "aws_cloudwatch_metric_alarm" "CIS_AWS_Config_Change_CW_Alarm" {
  alarm_name                = "CIS-3.9-AWSConfigChanges"
  comparison_operator       = "GreaterThanOrEqualToThreshold"
  evaluation_periods        = "1"
  metric_name               = aws_cloudwatch_log_metric_filter.CIS_AWS_Config_Change_Metric_Filter.id
  namespace                 = "CIS_Metric_Alarm_Namespace"
  period                    = "300"
  statistic                 = "Sum"
  threshold                 = "1"
  alarm_description         = "Monitoring changes to AWS Config configuration will help ensure sustained visibility of configuration items within the AWS account."
  alarm_actions             = [aws_sns_topic.CIS_Alerts_SNS_Topic.arn]
  insufficient_data_actions = []
}",
  "fix_summary": "Added a CloudWatch Log Group resource with retention_in_days set to 365 and KMS encryption enabled. Created a KMS key for encrypting the log group."
}
